create or replace TABLE KFL_PRODUCTION.DBP_DATA.ARTBEW_STUECKLISTE_ZU_1 (
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'ID der Artikelnummer per Stueckliste_1 mit Referenz zur Tabelle art_1',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Nummer des Marktes',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	DAT DATE NOT NULL COMMENT 'Datum des Abverkaufs, Format YYYY-MM_1-DD',
	KOMPONENTE_ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer der Stuecklistenkomponente mit referenz zur Tabelle art_1',
	STUECKLISTE_ID NUMBER(38,0) NOT NULL COMMENT 'Eindeutige ID der Stueckliste_1',
	WRG_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Kurzbezeichnung der Waehrung, z.Bsp. CZK, EUR',
	UMSATZ_NETTO NUMBER(18,4) NOT NULL COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag. Anteil aus Abverkauf auf Basis EKN1',
	UMSATZ_MWST_BETRAG NUMBER(18,4) NOT NULL COMMENT 'Der Mehrwertsteuerbetrag wird hier redundant abgelegt. Er ist eigentlich pro Artikel_1 als Mehrwertsteuersatz im Artikelstamm ersichtlich muss aber hier aus Performancegründen auch stehen.',
	MENGE NUMBER(18,3) NOT NULL COMMENT 'berechneter Wert aus Menge Abverkauf * Menge Komponente * Umrechnungsfaktor',
	EK_BRUTTO NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis brutto (bedeutung vgl. Kalkulationsschema).',
	EK_NETTO NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto (bedeutung vgl. Kalkulationsschema).',
	EK_NETTONETTO NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis nettonetto ((Bedeutung vgl. Kalkulationsschema).',
	EK_KAL_BASIS NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Kalkulationsbasis ((Bedeutung vgl. Kalkulationsschema).',
	EK_MEP NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis ((Bedeutung vgl. Kalkulationsschema).',
	EINSTANDSPREIS NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Kaufland Einstandspreis ((Bedeutung vgl. Kalkulationsschema).',
	LOGKOSTENZUSCHLAG NUMBER(18,4) COMMENT 'Logistikkostenzuschlag (ein kalkulierter Wert, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist)',
	EK_NETTO_BNK NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto plus Bezugsnebenkosten (Bedeutung vgl. Kalkulationsschema).',
	EK_NETTO_BNK_SACHK NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto plus Bezugsnebenkosten plus Sachkosten(Bedeutung vgl. Kalkulationsschema).',
	BQ_FINDUNG_ID NUMBER(38,0) NOT NULL COMMENT 'ID zur Kennzeichnung eines Ausstiegspunkts aus dem Kreisprozess.',
	UMRECHNUNGSKURS NUMBER(38,5) NOT NULL COMMENT 'Umrechnungskurs zur Umrechnung Landeswährung in Euro. Wird aus der Tabelle kurs_1 angereichert',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	EK_MEP_VOR_FWU NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis vor Festwertumlage: Mit Einführung der Festwertumlage in KMO braucht es einen \"alten\" EK3Netto ohne die Festwertumlage als Vergleichswert. Dieser Wert wird aus SAP über ZEKP.MEPOL geliefert.',
	BONUSBASIS NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Die Bonusbasis bildet für Artikel_1 mit Luxussteuer die Preisbasis der Reduzierungen nach Abzug der Luxussteuer auf der Ebene EK1N. Quelle: ZEKP.ABONBA',
	UMRECHNUNGSKURS_HIST NUMBER(38,5) NOT NULL DEFAULT 0 COMMENT 'Historischer Berichtskurs aus dbp_data.kurs_1 ',
	UMRECH_FAKTOR NUMBER(38,22) NOT NULL DEFAULT 1 COMMENT 'Umrechnungsfaktor für die Komponenten in einem VK_1-Set.',
	MENGE_KOMPONENTE_IN_VK_SET NUMBER(18,5) COMMENT 'Gewichstwert in der Mengeneinheit der Komponente in der Stückliste bzw. Verkaufsset (VK_1-Set) anteilig ihrer Menge.',
	constraint PK_ARTBEW_STUECKLISTE_ZU primary key (ART_ID, MANDANT_ID, WUP_ID, NB_ID, DAT, KOMPONENTE_ART_ID)
)COMMENT='AIS KMO - Hier werden die Stuecklistenartikel aus artbew_1 in ihre Positionen aufgeloest, um diese detailliert auswerten zu koennen.'
;